// Messe-Hub: turns one row of Sergii's lead_submissions (joined with companies/contacts and get_lead_status) into a dashboard lead.
const INTERESSE = { leadership: 'Führung', communication: 'Kommunikation', sales: 'Vertrieb', project_management: 'Projektmanagement', digital_skills: 'Digitale Kompetenzen', ai_automation: 'KI & Automatisierung', other: 'Sonstiges' };
const BUDGET = { approved: 'Genehmigt', planned: 'Geplant', unknown: 'Unklar', not_disclosed: 'Nicht genannt', no_budget: 'Kein Budget' };
const FOLLOW_UP = { within_one_week: 'Innerhalb 1 Woche', within_two_weeks: 'Innerhalb 2 Wochen', within_one_month: 'Innerhalb 1 Monat', on_date: 'Zum Termin', no_follow_up: 'Kein Follow-up', not_decided: 'Noch offen' };
const KATEGORIE = { HOT: 'A', WARM: 'B', COLD: 'C' };
const VERARBEITUNG = { pending: 'Wartet', processing: 'In Bearbeitung', completed: 'Fertig', failed: 'Fehler' };
const EMAIL_STATUS = { pending: 'Wartet', leased: 'Wird vorbereitet', sending: 'Wird gesendet', delivered: 'Gesendet', uncertain: 'Unklar – prüfen', failed: 'Fehlgeschlagen' };
const DUPLIKAT = { NEW: 'Neu', POSSIBLE_DUPLICATE: 'Mögliches Duplikat', EXISTING_CONTACT: 'Bekannter Kontakt' };
const GRUND = { training_interest: 'Trainingsinteresse', budget: 'Budget', follow_up: 'Follow-up', contactability: 'Erreichbarkeit', meeting_notes: 'Gesprächsnotiz', website: 'Website' };
const BASIS = { missing: 'fehlt', provided: 'vorhanden', provided_unverified: 'angegeben, nicht geprüft', email_or_phone_provided_unverified: 'E-Mail oder Telefon angegeben', name_only: 'nur Name', none: 'keine Angabe' };

// Copied from Sergii's processing library (scoreLead, version 1.0), so the dashboard explains the score exactly like WF-B computes it.
function scoreLead(lead) {
  // Version1.0: only captured structured fields and note presence earn points.
  // AI output and search ranking can never change the score.
  const breakdown = [];
  const add = (code,points,basis) => breakdown.push({code,points,basis});
  add('training_interest',!lead.training_interest ? 0 : lead.training_interest === 'other' ? 15 : 25,lead.training_interest ?? 'missing');
  add('budget',{approved:25,planned:15,unknown:5,not_disclosed:5,no_budget:0}[lead.budget_status] ?? 0,lead.budget_status ?? 'missing');
  let follow = {within_one_week:20,within_two_weeks:15,within_one_month:10}[lead.follow_up] ?? 0;
  if (lead.follow_up === 'on_date' && /^\d{4}-\d{2}-\d{2}$/.test(lead.follow_up_date ?? '')) {
    const reference = Date.parse(String(lead.captured_at).slice(0,10)+'T00:00:00Z');
    const delta = (Date.parse(lead.follow_up_date+'T00:00:00Z')-reference)/86400000;
    follow = !Number.isFinite(delta) ? 0 : delta <= 7 ? 20 : delta <= 14 ? 15 : delta <= 30 ? 10 : 5;
  }
  add('follow_up',follow,lead.follow_up === 'on_date' ? lead.follow_up_date : lead.follow_up ?? 'missing');
  add('contactability',lead.email || lead.phone ? 15 : lead.contact_name ? 5 : 0,lead.email || lead.phone ? 'email_or_phone_provided_unverified' : lead.contact_name ? 'name_only' : 'none');
  add('meeting_notes',typeof lead.notes === 'string' && [...lead.notes].length >= 10 ? 10 : 0,lead.notes ? 'provided' : 'missing');
  add('website',lead.website ? 5 : 0,lead.website ? 'provided_unverified' : 'missing');
  const total = breakdown.reduce((sum,x)=>sum+x.points,0);
  return {total,band:total >= 70 ? 'HOT' : total >= 40 ? 'WARM' : 'COLD',version:'1.0',breakdown};
}

function faelligAm(lead) {
  if (lead.follow_up === 'on_date' && /^\d{4}-\d{2}-\d{2}$/.test(lead.follow_up_date || '')) return lead.follow_up_date;
  const tage = { within_one_week: 7, within_two_weeks: 14, within_one_month: 30 }[lead.follow_up];
  if (!tage || !lead.captured_at) return null;
  const datum = new Date(lead.captured_at);
  if (isNaN(datum)) return null;
  datum.setUTCDate(datum.getUTCDate() + tage);
  return datum.toISOString().slice(0, 10);
}

function naechsterSchritt(lead) {
  const wer = lead.contact_name || 'Ansprechpartner';
  switch (lead.follow_up) {
    case 'within_one_week': return wer + ' innerhalb einer Woche kontaktieren';
    case 'within_two_weeks': return wer + ' innerhalb von zwei Wochen kontaktieren';
    case 'within_one_month': return wer + ' innerhalb eines Monats kontaktieren';
    case 'on_date': return wer + ' zum vereinbarten Termin kontaktieren';
    case 'no_follow_up': return 'Kein Follow-up gewünscht';
    default: return 'Follow-up festlegen';
  }
}

function leadAusZeile(z) {
  const d = z.daten || {};
  const st = z.status && z.status.success ? z.status : {};
  const lead = {
    training_interest: d.training_interest || null, budget_status: d.budget_status || null,
    follow_up: d.follow_up || null, follow_up_date: d.follow_up_date || null, captured_at: z.created_at || null,
    email: d.email || z.email || null, phone: d.phone || z.phone || null, contact_name: d.contact_name || z.contact_name || null,
    notes: d.notes || null, website: d.website || z.website || null,
  };
  const bewertung = scoreLead(lead);
  const ausDb = st.score_band && st.score_total !== null && st.score_total !== undefined;
  const score = ausDb ? Number(st.score_total) : bewertung.total;
  return {
    lead_id: z.lead_id,
    firma: d.company_name || z.company_name || '',
    kontakt: lead.contact_name || '',
    email: lead.email || '',
    telefon: lead.phone || '',
    website: lead.website || '',
    interesse: INTERESSE[lead.training_interest] || '',
    budget: BUDGET[lead.budget_status] || '',
    follow_up: FOLLOW_UP[lead.follow_up] || '',
    faellig_am: faelligAm(lead),
    naechster_schritt: naechsterSchritt(lead),
    notiz: d.notes || '',
    kategorie: KATEGORIE[ausDb ? st.score_band : bewertung.band] || '',
    score,
    vorlaeufig: !ausDb,
    verarbeitung: VERARBEITUNG[z.processing_status] || z.processing_status || '',
    verarbeitung_code: z.processing_status || '',
    email_status: EMAIL_STATUS[st.email_status] || '',
    email_code: st.email_status || '',
    duplikat: DUPLIKAT[z.duplicate_status] || z.duplicate_status || '',
    duplikat_code: z.duplicate_status || '',
    pruefen: Boolean(st.review_required ?? z.review_required),
    fehler: z.last_error_code || st.last_error_code || '',
    versuche: z.processing_attempts || 0,
    unsicherheiten: Array.isArray(z.uncertainty_flags) ? z.uncertainty_flags : [],
    erfasst: z.created_at || null,
    quelle: z.source || '',
    company_id: z.company_id || '',
    contact_id: z.contact_id || '',
    gruende: bewertung.breakdown.map((b) => ({
      grund: (GRUND[b.code] || b.code) + ': ' + (INTERESSE[b.basis] || BUDGET[b.basis] || FOLLOW_UP[b.basis] || BASIS[b.basis] || b.basis),
      punkte: b.points,
    })),
    gruppe_id: '',
    haupt: false,
    gruppe_groesse: 0,
  };
}

// Messe-Hub: rebuilds merge groups from the append-only history table "Messe-Hub Gruppen-Verlauf".
// Rows are never updated or deleted; merging, splitting and ignoring are events, so every step stays traceable and reversible.
function gruppenAusVerlauf(zeilen) {
  const ereignisse = zeilen
    .filter((z) => z && z.gruppe_id && z.aktion)
    .sort((a, b) => (Number(a.id) || 0) - (Number(b.id) || 0) || String(a.zeitpunkt).localeCompare(String(b.zeitpunkt)));
  const liste = (s) => String(s || '').split(',').map((x) => x.trim()).filter(Boolean);
  const gruppen = new Map();
  const ignoriert = new Set();
  for (const e of ereignisse) {
    const ids = liste(e.lead_ids);
    if (e.aktion === 'zusammengefuehrt') {
      liste(e.ersetzt).forEach((alt) => gruppen.delete(alt));
      gruppen.set(e.gruppe_id, { gruppe_id: e.gruppe_id, lead_ids: ids, haupt_lead_id: ids.includes(e.haupt_lead_id) ? e.haupt_lead_id : ids[0], grund: e.grund || '', von: e.von || '', zeitpunkt: e.zeitpunkt || '' });
    } else if (e.aktion === 'getrennt') {
      gruppen.delete(e.gruppe_id);
    } else if (e.aktion === 'herausgeloest') {
      const g = gruppen.get(e.gruppe_id);
      if (!g) continue;
      g.lead_ids = g.lead_ids.filter((x) => !ids.includes(x));
      if (!g.lead_ids.includes(g.haupt_lead_id)) g.haupt_lead_id = g.lead_ids[0];
      if (g.lead_ids.length < 2) gruppen.delete(e.gruppe_id);
    } else if (e.aktion === 'ignoriert') {
      ignoriert.add(ids.slice().sort().join(','));
    }
  }
  return { gruppen: [...gruppen.values()], ignoriert, ereignisse };
}


// One compact line per lead for the assistant's context; merged leads carry their group.
const chat = $('Frage an den Lead-Assistenten').first().json;
const zeilen = $('Leads lesen').first().json.leads || [];
const { gruppen } = gruppenAusVerlauf($input.all().map((i) => i.json));
const gruppeVon = new Map();
gruppen.forEach((g) => g.lead_ids.forEach((id) => gruppeVon.set(id, g)));

const leads = zeilen.map(leadAusZeile).map((l) => {
  const g = gruppeVon.get(l.lead_id);
  return {
    id: l.lead_id, firma: l.firma, kontakt: l.kontakt, email: l.email, telefon: l.telefon, website: l.website,
    training: l.interesse, budget: l.budget, follow_up: l.follow_up, faellig_am: l.faellig_am, naechster_schritt: l.naechster_schritt,
    kategorie: l.kategorie + (l.vorlaeufig ? ' (vorläufig)' : ''), punkte: l.score,
    bewertung: l.gruende.map((x) => x.grund + ' = ' + x.punkte).join('; '),
    verarbeitung: l.verarbeitung, email_bericht: l.email_status, duplikat: l.duplikat,
    gruppe: g ? g.gruppe_id + (g.haupt_lead_id === l.lead_id ? ' (Hauptlead)' : ' (zusammengeführt mit ' + g.haupt_lead_id + ')') : '',
    erfasst: l.erfasst, notiz: [...l.notiz].slice(0, 800).join(''),
  };
});

return [{
  json: {
    sessionId: chat.sessionId,
    chatInput: String(chat.chatInput || '').trim(),
    anzahl: leads.length,
    leads_text: leads.length ? leads.map((l) => JSON.stringify(l)).join('\n') : '(noch keine Leads in der Datenbank)',
  },
}];
